def solve(rows):
    if not rows:
        return []
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 5 != 2 or i == len(rows) - 1:
            filtered_rows.append(row)
    if filtered_rows:
        n = len(filtered_rows)
        rotation_amount = 3 % n
        rotated_rows = filtered_rows[rotation_amount:] + filtered_rows[:rotation_amount]
    else:
        rotated_rows = []
    sorted_rows = sorted(list(set(rotated_rows)))
    sessions = []
    if sorted_rows:
        start = sorted_rows[0]
        end = sorted_rows[0]
        count = 1
        for i in range(1, len(sorted_rows)):
            if sorted_rows[i] - end >= 8:
                sessions.append([start, end, count])
                start = sorted_rows[i]
                end = sorted_rows[i]
                count = 1
            else:
                end = sorted_rows[i]
                count += 1
        sessions.append([start, end, count])
    return sessions

